import XCTest
final class UITapTests: XCTestCase {
  func testAcceptBlueskyLink() {
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    let openButton = springboard.alerts.buttons["Open"]
    if openButton.waitForExistence(timeout: 5) {
      openButton.tap()
    } else {
      let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
      app.activate()
      XCTAssertTrue(openButton.waitForExistence(timeout: 10), "Expected the Bluesky URL confirmation")
      openButton.tap()
    }
  }
}
EOF

